1	"use client";
2	
3	import { useActionState, useEffect, useState, useTransition } from "react";
4	import {
5	  deleteFreeMinecraftServer,
6	  startFreeMinecraftServer,
7	  stopFreeMinecraftServer,
8	  restartFreeMinecraftServer,
9	  renameFreeMinecraftServer,
10	  changeFreeMinecraftSubdomain,
11	  sendFreeMinecraftCommand,
12	  getFreeMinecraftPlayers,
13	  applyFreeMinecraftSettings,
14	  applyFreeMinecraftPreset,
15	} from "@/lib/actions-free-minecraft";
16	import { PublicListingCard } from "./PublicListingCard";
17	import { InventoryEditor } from "./InventoryEditor";
18	import { ModsTab } from "./ModsTab";
19	import { RolesTab } from "./RolesTab";
20	
21	type Server = {
22	  id: string;
23	  subdomain: string;
24	  name: string | null;
25	  preset: string;
26	  running: boolean;
27	  players: { online: number; max: number } | null;
28	  isPublic: boolean;
29	  publicTagline: string | null;
30	  publicDescription: string | null;
31	  extraMods: string[];
32	};
33	
34	type Field = {
35	  key: string;
36	  label: string;
37	  group: string;
38	  type: "enum" | "bool" | "int" | "string";
39	  default: string | number | boolean;
40	  options?: { value: string; label: string }[];
41	  min?: number;
42	  max?: number;
43	  phase: "deploy" | "live";
44	  help?: string;
45	};
46	
47	type Preset = {
48	  label: string;
49	  description: string;
50	  kind: "properties" | "plugins";
51	  properties: Record<string, string>;
52	  setupNote?: string;
53	  heroImage?: string;
54	};
55	
56	const TABS = [
57	  { key: "overview", label: "Overview" },
58	  { key: "console", label: "Console" },
59	  { key: "players", label: "Players" },
60	  { key: "mods", label: "Mods" },
61	  { key: "roles", label: "Roles" },
62	  { key: "settings", label: "Settings" },
63	  { key: "manage", label: "Manage" },
64	] as const;
65	type TabKey = (typeof TABS)[number]["key"];
66	
67	export function FreeMcDashboard({
68	  server,
69	  domain,
70	  schemaFields,
71	  properties,
72	  presets,
73	}: {
74	  server: Server;
75	  domain: string;
76	  schemaFields: Field[];
77	  properties: Record<string, string>;
78	  presets: Record<string, Preset>;
79	}) {
80	  const [tab, setTab] = useState<TabKey>("overview");
81	  const address = `${server.subdomain}.${domain}`;
82	
83	  return (
84	    <div className="space-y-6">
85	      <div className="card flex flex-wrap items-center justify-between gap-4">
86	        <div>
87	          <div className="flex items-center gap-2.5">
88	            <span className={`h-2.5 w-2.5 rounded-full ${server.running ? "bg-emerald-400" : "bg-slate-500"}`} />
89	            <h2 className="text-lg font-semibold text-white">{server.name || server.subdomain}</h2>
90	            <span className="text-xs text-slate-500">{server.running ? "Awake" : "Asleep"}</span>
91	          </div>
92	          <div className="mt-1 flex items-center gap-2">
93	            <code className="text-sm text-slate-400">{address}</code>
94	            <button type="button" className="btn-ghost text-xs" onClick={() => navigator.clipboard.writeText(address)}>
95	              Copy
96	            </button>
97	          </div>
98	        </div>
99	        <div className="text-right">
100	          <p className="text-sm text-slate-400">
101	            {server.running ? `${server.players?.online ?? 0} / ${server.players?.max ?? "?"} online` : "Nobody connected — sleeping"}
102	          </p>
103	          <PowerButtons running={server.running} />
104	        </div>
105	      </div>
106	
107	      <div className="flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1">
108	        {TABS.map((t) => (
109	          <button
110	            key={t.key}
111	            type="button"
112	            onClick={() => setTab(t.key)}
113	            className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
114	              tab === t.key ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
115	            }`}
116	          >
117	            {t.label}
118	          </button>
119	        ))}
120	      </div>
121	
122	      {tab === "overview" && <Overview server={server} presets={presets} />}
123	      {tab === "console" && <Console running={server.running} />}
124	      {tab === "players" && (
125	        <div className="space-y-6">
126	          <Players running={server.running} />
127	          <InventoryEditor running={server.running} />
128	        </div>
129	      )}
130	      {tab === "mods" && <ModsTab server={server} runsPlugins={presets[server.preset]?.kind === "plugins"} />}
131	      {tab === "roles" && <RolesTab presetKind={presets[server.preset]?.kind ?? "properties"} />}
132	      {tab === "settings" && <Settings fields={schemaFields} properties={properties} />}
133	      {tab === "manage" && <Manage server={server} domain={domain} />}
134	    </div>
135	  );
136	}
137	
138	function PowerButtons({ running }: { running: boolean }) {
139	  const [, startAction, startPending] = useActionState(startFreeMinecraftServer, {});
140	  const [, stopAction, stopPending] = useActionState(stopFreeMinecraftServer, {});
141	  const [, restartAction, restartPending] = useActionState(restartFreeMinecraftServer, {});
142	  const busy = startPending || stopPending || restartPending;
143	  return (
144	    <div className="mt-2 flex justify-end gap-2">
145	      {!running ? (
146	        <form action={startAction}>
147	          <button className="btn-primary text-xs" disabled={busy}>{startPending ? "Starting…" : "Start"}</button>
148	        </form>
149	      ) : (
150	        <>
151	          <form action={restartAction}>
152	            <button className="btn-secondary text-xs" disabled={busy}>{restartPending ? "Restarting…" : "Restart"}</button>
153	          </form>
154	          <form action={stopAction}>
155	            <button className="btn-ghost text-xs" disabled={busy}>{stopPending ? "Stopping…" : "Stop"}</button>
156	          </form>
157	        </>
158	      )}
159	    </div>
160	  );
161	}
162	
163	function Overview({ server, presets }: { server: Server; presets: Record<string, Preset> }) {
164	  const [, action, pending] = useActionState(applyFreeMinecraftPreset, {});
165	  const [selected, setSelected] = useState<string | null>(null);
166	  return (
167	    <div className="card">
168	      <h3 className="font-semibold text-[var(--fg)]">Quick-start presets</h3>
169	      <p className="mt-1 text-sm text-slate-400">
170	        Applying a preset restarts your server. Presets that add plugins take a little longer the first time while
171	        they download.
172	      </p>
173	      <div className="mt-4 grid gap-3 sm:grid-cols-2">
174	        {Object.entries(presets).map(([key, p]) => {
175	          // Highlight whatever the user just clicked, not just the server's
176	          // last-known active preset — otherwise clicking a different card
177	          // silently updates the pending selection with zero visible feedback
178	          // until the page reloads after Apply, which reads as "nothing happened".
179	          const isChosen = selected ? selected === key : server.preset === key;
180	          const isPendingChange = selected !== null && selected === key && server.preset !== key;
181	          return (
182	          <label
183	            key={key}
184	            className={`flex cursor-pointer flex-col gap-1 overflow-hidden rounded-xl border text-sm transition-colors ${
185	              isChosen ? "border-brand-400/50 bg-brand-500/10" : "border-white/[0.08] hover:border-white/20"
186	            }`}
187	          >
188	            {p.heroImage && (
189	              // eslint-disable-next-line @next/next/no-img-element
190	              <img
191	                src={p.heroImage}
192	                alt=""
193	                aria-hidden
194	                className="h-24 w-full object-cover"
195	                loading="lazy"
196	              />
197	            )}
198	            <div className="flex flex-col gap-1 px-4 py-3">
199	              <div className="flex items-center justify-between">
200	                <span className="font-medium text-[var(--fg)]">{p.label}</span>
201	                {server.preset === key && <span className="text-xs text-brand-300">Active</span>}
202	                {isPendingChange && <span className="text-xs text-amber-300">Selected</span>}
203	              </div>
204	              <span className="text-xs text-slate-500">{p.description}</span>
205	              {p.setupNote && <span className="text-xs text-amber-300/80">{p.setupNote}</span>}
206	            </div>
207	            <input
208	              type="radio"
209	              name="preset-radio"
210	              className="hidden"
211	              checked={selected === key}
212	              onChange={() => setSelected(key)}
213	            />
214	          </label>
215	          );
216	        })}
217	      </div>
218	      <form action={action} className="mt-4">
219	        <input type="hidden" name="preset" value={selected ?? ""} />
220	        <button className="btn-primary text-sm" disabled={!selected || pending}>
221	          {pending ? "Applying…" : "Apply preset"}
222	        </button>
223	      </form>
224	    </div>
225	  );
226	}
227	
228	function Console({ running }: { running: boolean }) {
229	  const [log, setLog] = useState<{ cmd: string; out: string; err?: boolean }[]>([]);
230	  const [pending, startTransition] = useTransition();
231	
232	  function submit(formData: FormData) {
233	    const cmd = String(formData.get("command") ?? "");
234	    if (!cmd.trim()) return;
235	    startTransition(async () => {
236	      const res = await sendFreeMinecraftCommand({}, formData);
237	      setLog((l) => [...l, { cmd, out: res.error ?? res.response ?? "", err: !!res.error }]);
238	    });
239	  }
240	
241	  return (
242	    <div className="card">
243	      <h3 className="font-semibold text-[var(--fg)]">Console</h3>
244	      {!running && (
245	        <p className="mt-1 text-sm text-amber-300">Server is asleep — commands won&apos;t reach it until someone connects.</p>
246	      )}
247	      <div className="mt-3 h-64 overflow-y-auto rounded-lg border border-white/10 bg-black/40 p-3 font-mono text-xs">
248	        {log.length === 0 && <p className="text-slate-600">Command output will appear here.</p>}
249	        {log.map((l, i) => (
250	          <div key={i} className="mb-2">
251	            <p className="text-brand-300">&gt; {l.cmd}</p>
252	            <p className={l.err ? "text-red-400" : "text-slate-300"}>{l.out}</p>
253	          </div>
254	        ))}
255	      </div>
256	      <form action={submit} className="mt-3 flex gap-2">
257	        <input className="input flex-1 font-mono text-sm" name="command" placeholder="say hello" maxLength={512} autoComplete="off" />
258	        <button className="btn-primary text-sm" disabled={pending}>{pending ? "…" : "Send"}</button>
259	      </form>
260	    </div>
261	  );
262	}
263	
264	function Players({ running }: { running: boolean }) {
265	  const [players, setPlayers] = useState<{ name: string }[] | null>(null);
266	  const [error, setError] = useState<string | null>(null);
267	  const [pending, startTransition] = useTransition();
268	
269	  function refresh() {
270	    startTransition(async () => {
271	      const res = await getFreeMinecraftPlayers();
272	      if (res.ok) { setPlayers(res.players); setError(null); }
273	      else { setError(res.error); setPlayers(null); }
274	    });
275	  }
276	  useEffect(() => { if (running) refresh(); }, [running]);
277	
278	  return (
279	    <div className="card">
280	      <div className="flex items-center justify-between">
281	        <h3 className="font-semibold text-[var(--fg)]">Players online</h3>
282	        <button type="button" className="btn-ghost text-xs" onClick={refresh} disabled={pending}>
283	          {pending ? "Refreshing…" : "Refresh"}
284	        </button>
285	      </div>
286	      {!running ? (
287	        <p className="mt-3 text-sm text-slate-500">Server is asleep — nobody&apos;s connected.</p>
288	      ) : error ? (
289	        <p className="mt-3 text-sm text-red-400">{error}</p>
290	      ) : players && players.length === 0 ? (
291	        <p className="mt-3 text-sm text-slate-500">No one&apos;s online right now.</p>
292	      ) : players ? (
293	        <ul className="mt-3 space-y-1.5">
294	          {players.map((p) => (
295	            <li key={p.name} className="flex items-center gap-2 rounded-lg border border-white/[0.06] px-3 py-2 text-sm">
296	              <span className="h-2 w-2 rounded-full bg-emerald-400" /> {p.name}
297	            </li>
298	          ))}
299	        </ul>
300	      ) : null}
301	    </div>
302	  );
303	}
304	
305	function Settings({ fields, properties }: { fields: Field[]; properties: Record<string, string> }) {
306	  const [state, action, pending] = useActionState(applyFreeMinecraftSettings, {});
307	  const groups = [...new Set(fields.map((f) => f.group))];
308	
309	  return (
310	    <form action={action} className="card space-y-6">
311	      {state.error && (
312	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
313	      )}
314	      {groups.map((group) => (
315	        <div key={group}>
316	          <h3 className="font-semibold text-[var(--fg)]">{group}</h3>
317	          <div className="mt-3 space-y-4">
318	            {fields.filter((f) => f.group === group).map((f) => (
319	              <FieldInput key={f.key} field={f} value={properties[f.key]} />
320	            ))}
321	          </div>
322	        </div>
323	      ))}
324	      <button className="btn-primary text-sm" disabled={pending}>{pending ? "Applying…" : "Save & restart"}</button>
325	      <p className="text-xs text-slate-500">Saving restarts your server to apply every change consistently.</p>
326	    </form>
327	  );
328	}
329	
330	function FieldInput({ field, value }: { field: Field; value: string | undefined }) {
331	  const current = value ?? String(field.default);
332	  const liveTag = field.phase === "live" ? (
333	    <span className="rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-300">applies instantly</span>
334	  ) : (
335	    <span className="rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-semibold text-amber-300">needs restart</span>
336	  );
337	
338	  return (
339	    <div>
340	      <div className="flex items-center gap-2">
341	        <label className="label mb-0">{field.label}</label>
342	        {liveTag}
343	      </div>
344	      {field.type === "enum" && (
345	        <select className="input mt-1" name={field.key} defaultValue={current}>
346	          {field.options?.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
347	        </select>
348	      )}
349	      {field.type === "bool" && (
350	        <select className="input mt-1" name={field.key} defaultValue={current}>
351	          <option value="true">On</option>
352	          <option value="false">Off</option>
353	        </select>
354	      )}
355	      {field.type === "int" && (
356	        <input className="input mt-1" type="number" name={field.key} defaultValue={current} min={field.min} max={field.max} />
357	      )}
358	      {field.type === "string" && (
359	        <input className="input mt-1" type="text" name={field.key} defaultValue={current} maxLength={100} />
360	      )}
361	      {field.help && <p className="mt-1 text-xs text-slate-500">{field.help}</p>}
362	    </div>
363	  );
364	}
365	
366	function Manage({ server, domain }: { server: Server; domain: string }) {
367	  const [renameState, renameAction, renamePending] = useActionState(renameFreeMinecraftServer, {});
368	  const [subState, subAction, subPending] = useActionState(changeFreeMinecraftSubdomain, {});
369	  const [deleteState, deleteAction, deletePending] = useActionState(deleteFreeMinecraftServer, {});
370	
371	  return (
372	    <div className="space-y-6">
373	      <form action={renameAction} className="card max-w-md space-y-3">
374	        <h3 className="font-semibold text-[var(--fg)]">Server name</h3>
375	        <p className="text-xs text-slate-500">Cosmetic label shown in your dashboard — doesn&apos;t change how you connect.</p>
376	        {renameState.error && <p className="text-sm text-red-400">{renameState.error}</p>}
377	        <input className="input" name="name" defaultValue={server.name ?? server.subdomain} maxLength={40} />
378	        <button className="btn-secondary text-sm" disabled={renamePending}>{renamePending ? "Saving…" : "Save name"}</button>
379	      </form>
380	
381	      <form action={subAction} className="card max-w-md space-y-3">
382	        <h3 className="font-semibold text-[var(--fg)]">Connect address</h3>
383	        <p className="text-xs text-slate-500">Changing this moves your server to a new subdomain — your world stays intact, but there&apos;s a few seconds of downtime while it moves.</p>
384	        {subState.error && <p className="text-sm text-red-400">{subState.error}</p>}
385	        <div className="flex items-center gap-2">
386	          <input
387	            className="input"
388	            name="subdomain"
389	            defaultValue={server.subdomain}
390	            minLength={3}
391	            maxLength={20}
392	            pattern="[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?"
393	          />
394	          <span className="whitespace-nowrap text-sm text-slate-400">.{domain}</span>
395	        </div>
396	        <button className="btn-secondary text-sm" disabled={subPending}>{subPending ? "Moving…" : "Change address"}</button>
397	      </form>
398	
399	      <PublicListingCard server={server} />
400	
401	      <form action={deleteAction} className="card max-w-md space-y-3">
402	        <h3 className="font-semibold text-red-300">Delete this server</h3>
403	        <p className="text-xs text-slate-500">Permanent — your world is deleted along with the server. This can&apos;t be undone.</p>
404	        {deleteState.error && <p className="text-sm text-red-400">{deleteState.error}</p>}
405	        <button className="btn-ghost text-sm text-red-300" disabled={deletePending}>{deletePending ? "Deleting…" : "Delete this server"}</button>
406	      </form>
407	    </div>
408	  );
409	}
410

1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { AutoRefresh } from "@/components/AutoRefresh";
5	import { EmptyState, StatusDot } from "@/components/ui/primitives";
6	import { PortalHero } from "@/components/portal/PortalHero";
7	import { DeployButton } from "@/components/customer/DeployButton";
8	import { GAME_DISPLAY } from "@/lib/games";
9	import { FreeMinecraftTabContent } from "@/components/customer/freemc/FreeMinecraftTabContent";
10	
11	export const dynamic = "force-dynamic";
12	
13	// Manage-existing view only. The deploy/checkout wizard (GameDeployWizard) now lives
14	// solely on /dashboard/deploy?product=game — a single source of truth for the
15	// money-audited flow. This page lists + manages the customer's existing game servers.
16	//
17	// Two tabs, picked via ?tab= so only the active one's data actually gets fetched
18	// (the Free Minecraft tab does an SSH status round-trip to freemc-host — no reason
19	// to pay that cost on every games-page view when most people are looking at their
20	// paid servers). "Free Minecraft" used to be its own sidebar entry; it moved here
21	// and the sidebar now shows a green "FREE" tag on Game Servers instead (see
22	// app/dashboard/layout.tsx). /dashboard/free-minecraft itself still works — the
23	// marketing site and the public server directory deep-link straight to it.
24	export default async function DashboardGamesPage({
25	  searchParams,
26	}: {
27	  searchParams: Promise<{ tab?: string }>;
28	}) {
29	  const { tab } = await searchParams;
30	  const activeTab = tab === "free" ? "free" : "servers";
31	  const user = await requireUser();
32	
33	  return (
34	    <div className="space-y-6">
35	      <PortalHero
36	        variant="games"
37	        title="Game servers"
38	        sub="Your ready-to-play game servers — sized and priced per game."
39	      >
40	        <DeployButton href="/dashboard/deploy?product=game">Deploy game server</DeployButton>
41	      </PortalHero>
42	
43	      <div className="flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1">
44	        <Link
45	          href="/dashboard/games"
46	          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
47	            activeTab === "servers"
48	              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
49	              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
50	          }`}
51	        >
52	          My Servers
53	        </Link>
54	        <Link
55	          href="/dashboard/games?tab=free"
56	          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
57	            activeTab === "free"
58	              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
59	              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
60	          }`}
61	        >
62	          Free Minecraft
63	          <span className="ml-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-emerald-300">
64	            Free
65	          </span>
66	        </Link>
67	      </div>
68	
69	      {activeTab === "free" ? (
70	        <FreeMinecraftTabContent />
71	      ) : (
72	        <PaidGameServers userId={user.id} />
73	      )}
74	    </div>
75	  );
76	}
77	
78	async function PaidGameServers({ userId }: { userId: string }) {
79	  const servers = await db.server.findMany({
80	    where: { userId, gamePlanId: { not: null } },
81	    include: { plan: true, osTemplate: true, gamePlan: true },
82	    orderBy: { createdAt: "desc" },
83	  });
84	
85	  const transitional = servers.some((s) =>
86	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
87	  );
88	
89	  return (
90	    <>
91	      {transitional && <AutoRefresh />}
92	      {servers.length === 0 ? (
93	        <EmptyState
94	          title="No game servers yet"
95	          sub="Spin up a ready-to-play Minecraft, Rust, Valheim or Palworld server in minutes."
96	          action={
97	            <DeployButton href="/dashboard/deploy?product=game">Deploy your first game server</DeployButton>
98	          }
99	        />
100	      ) : (
101	        <div className="grid gap-3 sm:grid-cols-2">
102	          {servers.map((s) => {
103	            const family = s.osTemplate.family;
104	            const meta = GAME_DISPLAY[family as keyof typeof GAME_DISPLAY] ?? { name: family, glyph: "🎮" };
105	            return (
106	              <Link
107	                key={s.id}
108	                href={`/dashboard/servers/${s.id}`}
109	                className="card card-hover block transition"
110	              >
