/**
 * Hand-authored SVG -> JPEG art generator for the free-Minecraft game-type
 * cards + the dashboard top-card hero.
 *
 * All artwork here is ORIGINAL geometric/voxel illustration in the Nxeon
 * palette. Nothing is traced from, or reproduces, any Mojang/Minecraft asset
 * or character design.
 *
 * Palette anchors:
 *   navy    #0a0e1a -> #0f1420
 *   violet  #6f47f5 / #8b5cf6
 *   cyan    #06b6d4 / blue #3b82f6
 * Warm accents (sunset orange/amber) are used where the brief calls for them.
 */
import sharp from "sharp";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const OUT = process.argv[2] || "/opt/nxeon-wt-freemcredesign/public/games/art";
mkdirSync(OUT, { recursive: true });

const CARD_W = 800;
const CARD_H = 1000;

/* ------------------------------------------------------------------ utils */

function rng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

const f = (n) => Number(n.toFixed(2));

/** Scattered blocky "pixel dust" — small axis-aligned squares, the texture
 *  that ties every one of these scenes to the voxel language. */
function pixelDust({ seed, count, w, h, y0 = 0, y1 = h, color, minS = 2, maxS = 7, opacity = 0.5 }) {
  const r = rng(seed);
  let out = "";
  for (let i = 0; i < count; i++) {
    const s = minS + r() * (maxS - minS);
    const x = r() * w;
    const y = y0 + r() * (y1 - y0);
    const o = opacity * (0.25 + r() * 0.75);
    out += `<rect x="${f(x)}" y="${f(y)}" width="${f(s)}" height="${f(s)}" fill="${color}" opacity="${f(o)}"/>`;
  }
  return out;
}

function stars({ seed, count, w, h, color = "#dbeafe" }) {
  const r = rng(seed);
  let out = "";
  for (let i = 0; i < count; i++) {
    const s = r() < 0.15 ? 3 : 2;
    out += `<rect x="${f(r() * w)}" y="${f(r() * h)}" width="${s}" height="${s}" fill="${color}" opacity="${f(0.15 + r() * 0.6)}"/>`;
  }
  return out;
}

/** A stepped, blocky horizon ridge — voxel terrain rather than a smooth curve. */
function blockRidge({ x0, x1, baseY, amp, step, seed, fill, floorY, opacity = 1 }) {
  const r = rng(seed);
  const pts = [];
  let y = baseY;
  for (let x = x0; x <= x1; x += step) {
    y += (r() - 0.5) * amp;
    y = Math.max(baseY - amp * 2.2, Math.min(baseY + amp * 1.4, y));
    pts.push([x, Math.round(y / step) * step]);
  }
  let d = `M ${x0} ${floorY}`;
  for (const [px, py] of pts) d += ` L ${f(px)} ${f(py)} L ${f(px + step)} ${f(py)}`;
  d += ` L ${x1} ${floorY} Z`;
  return `<path d="${d}" fill="${fill}" opacity="${opacity}"/>`;
}

/**
 * Blocky humanoid adventurer, built from cubes. Deliberately generic: hooded/
 * helmeted head, no facial features, no signature colour combination — an
 * original voxel figure, not a likeness of any established game character.
 */
function voxelFigure({
  x,
  y,
  u,
  body = "#140c24",
  shade = "#0b0714",
  accent = null,
  pose = "stand",
  flip = false,
  sword = null,
}) {
  const t = flip ? `translate(${f(x)},${f(y)}) scale(-1,1)` : `translate(${f(x)},${f(y)})`;
  const B = (px, py, pw, ph, c = body) =>
    `<rect x="${f(px * u)}" y="${f(py * u)}" width="${f(pw * u)}" height="${f(ph * u)}" fill="${c}"/>`;

  let parts = "";
  // head (4u) + torso (4u wide, 6u tall), origin at figure's top-left
  parts += B(0, 0, 4, 4);
  parts += B(0, 0, 4, 1, shade); // helmet crown highlight band
  if (accent) parts += B(0, 3.2, 4, 0.8, accent); // visor/scarf band
  parts += B(0, 4, 4, 6); // torso
  parts += B(0, 4, 4, 0.9, shade);

  if (pose === "leap") {
    parts += `<g transform="rotate(-32 ${f(0)} ${f(4.4 * u)})">${B(-2, 4.2, 2, 6)}</g>`;
    parts += `<g transform="rotate(38 ${f(4 * u)} ${f(4.4 * u)})">${B(4, 4.2, 2, 6)}</g>`;
    parts += `<g transform="rotate(-40 ${f(1 * u)} ${f(10 * u)})">${B(0, 10, 2, 6)}</g>`;
    parts += `<g transform="rotate(22 ${f(3 * u)} ${f(10 * u)})">${B(2, 10, 2, 6)}</g>`;
  } else if (pose === "ready") {
    parts += `<g transform="rotate(-46 ${f(0)} ${f(4.4 * u)})">${B(-2, 4.2, 2, 6)}</g>`;
    parts += B(4, 4.2, 2, 6);
    parts += B(0, 10, 2, 6);
    parts += `<g transform="rotate(16 ${f(3 * u)} ${f(10 * u)})">${B(2, 10, 2, 6)}</g>`;
  } else {
    parts += B(-2, 4.2, 2, 6);
    parts += B(4, 4.2, 2, 6);
    parts += B(0, 10, 2, 6);
    parts += B(2, 10, 2, 6);
  }

  if (sword) {
    const { blade = "#7dd3fc", grip = "#2a1c46", guard = "#8b5cf6", angle = -34, gx = -2.6, gy = 3.4, glow = null } = sword;
    let s = "";
    s += `<rect x="${f(-0.7 * u)}" y="${f(-9 * u)}" width="${f(1.4 * u)}" height="${f(9 * u)}" fill="${blade}"/>`;
    s += `<rect x="${f(-0.7 * u)}" y="${f(-9 * u)}" width="${f(0.5 * u)}" height="${f(9 * u)}" fill="#ffffff" opacity="0.45"/>`;
    s += `<rect x="${f(-1.9 * u)}" y="${f(0)}" width="${f(3.8 * u)}" height="${f(0.9 * u)}" fill="${guard}"/>`;
    s += `<rect x="${f(-0.5 * u)}" y="${f(0.9 * u)}" width="${f(1 * u)}" height="${f(2.4 * u)}" fill="${grip}"/>`;
    parts += `<g transform="translate(${f(gx * u)},${f(gy * u)}) rotate(${angle})">${
      glow ? `<rect x="${f(-1.6 * u)}" y="${f(-9.6 * u)}" width="${f(3.2 * u)}" height="${f(10 * u)}" fill="${glow}" opacity="0.35" filter="url(#softglow)"/>` : ""
    }${s}</g>`;
  }

  return `<g transform="${t}">${parts}</g>`;
}

/** Isometric-ish floating island: flat blocky top plate + tapering underside. */
function floatingIsland({ cx, cy, w, topH = 26, depth, top, side, under, edge = null }) {
  const hw = w / 2;
  let out = "";
  // tapering underside, built from stacked shrinking slabs (voxel strata)
  const layers = 7;
  for (let i = 0; i < layers; i++) {
    const t = i / (layers - 1);
    const lw = hw * (1 - t * 0.82);
    const ly = cy + topH + (depth * i) / layers;
    const lh = depth / layers + 2;
    const c = i < 2 ? side : under;
    out += `<rect x="${f(cx - lw)}" y="${f(ly)}" width="${f(lw * 2)}" height="${f(lh)}" fill="${c}"/>`;
  }
  out += `<rect x="${f(cx - hw)}" y="${f(cy)}" width="${f(w)}" height="${f(topH)}" fill="${top}"/>`;
  if (edge) out += `<rect x="${f(cx - hw)}" y="${f(cy)}" width="${f(w)}" height="6" fill="${edge}" opacity="0.6"/>`;
  return out;
}

/** Blocky tree: cube trunk + a stepped canopy of leaf cubes. */
function voxelTree({ x, y, u, trunk = "#4a3320", leaf = "#22d3a5", leafDark = "#0f8f74" }) {
  let out = "";
  out += `<rect x="${f(x - u * 0.6)}" y="${f(y - u * 3)}" width="${f(u * 1.2)}" height="${f(u * 3)}" fill="${trunk}"/>`;
  const rows = [
    [3.4, 1.2, 5.2],
    [4.6, 1.2, 5.2],
    [5.8, 1.0, 3.6],
    [6.8, 0.7, 2.2],
  ];
  for (const [dy, hh, ww] of rows) {
    out += `<rect x="${f(x - (ww * u) / 2)}" y="${f(y - u * (dy + hh))}" width="${f(ww * u)}" height="${f(hh * u)}" fill="${leaf}"/>`;
    out += `<rect x="${f(x - (ww * u) / 2)}" y="${f(y - u * (dy + hh))}" width="${f(ww * u)}" height="${f(u * 0.28)}" fill="#ffffff" opacity="0.14"/>`;
    out += `<rect x="${f(x + (ww * u) / 2 - u * 0.55)}" y="${f(y - u * (dy + hh))}" width="${f(u * 0.55)}" height="${f(hh * u)}" fill="${leafDark}" opacity="0.55"/>`;
  }
  return out;
}

/** Blocky cottage with warm lit windows. */
function voxelHouse({ x, y, w, h, wall, roof, window: win = "#fbbf24", glow = true, roofOverhang = 0.16 }) {
  const ow = w * (1 + roofOverhang);
  let out = "";
  out += `<rect x="${f(x - w / 2)}" y="${f(y - h)}" width="${f(w)}" height="${f(h)}" fill="${wall}"/>`;
  out += `<path d="M ${f(x - ow / 2)} ${f(y - h)} L ${f(x)} ${f(y - h - w * 0.52)} L ${f(x + ow / 2)} ${f(y - h)} Z" fill="${roof}"/>`;
  const wsz = Math.max(4, w * 0.17);
  const wins = [
    [x - w * 0.24, y - h * 0.66],
    [x + w * 0.24, y - h * 0.66],
    [x - w * 0.24, y - h * 0.3],
  ];
  for (const [wx, wy] of wins) {
    if (glow)
      out += `<rect x="${f(wx - wsz)}" y="${f(wy - wsz)}" width="${f(wsz * 2)}" height="${f(wsz * 2)}" fill="${win}" opacity="0.32" filter="url(#softglow)"/>`;
    out += `<rect x="${f(wx - wsz / 2)}" y="${f(wy - wsz / 2)}" width="${f(wsz)}" height="${f(wsz)}" fill="${win}"/>`;
  }
  return out;
}

const DEFS = `
<filter id="softglow" x="-80%" y="-80%" width="260%" height="260%">
  <feGaussianBlur stdDeviation="14"/>
</filter>
<filter id="bigglow" x="-100%" y="-100%" width="300%" height="300%">
  <feGaussianBlur stdDeviation="42"/>
</filter>
<filter id="tinyglow" x="-120%" y="-120%" width="340%" height="340%">
  <feGaussianBlur stdDeviation="5"/>
</filter>
<filter id="mist" x="-40%" y="-40%" width="180%" height="180%">
  <feGaussianBlur stdDeviation="26"/>
</filter>
`;

function vignette(w, h, strength = 0.55) {
  return `<rect width="${w}" height="${h}" fill="url(#vig)" opacity="${strength}"/>`;
}
const VIG_DEF = `
<radialGradient id="vig" cx="50%" cy="44%" r="76%">
  <stop offset="55%" stop-color="#000000" stop-opacity="0"/>
  <stop offset="100%" stop-color="#000000" stop-opacity="0.85"/>
</radialGradient>`;

function svg(w, h, defs, body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
<defs>${DEFS}${VIG_DEF}${defs}</defs>
${body}
</svg>`;
}

/* ------------------------------------------------------------------ scenes */

const W = CARD_W;
const H = CARD_H;

/** Vanilla — calm sunset landscape, small house + tree silhouette. */
function sceneVanilla() {
  const defs = `
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#1b1140"/>
    <stop offset="32%" stop-color="#3d1f57"/>
    <stop offset="56%" stop-color="#8b3f5c"/>
    <stop offset="74%" stop-color="#d97544"/>
    <stop offset="86%" stop-color="#f0a martin"/>
  </linearGradient>`;
  // (guard against typos: rebuild gradient cleanly)
  const skyDef = `
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#160e36"/>
    <stop offset="30%" stop-color="#3a1e55"/>
    <stop offset="54%" stop-color="#8b3f5c"/>
    <stop offset="72%" stop-color="#d97544"/>
    <stop offset="84%" stop-color="#f3b26a"/>
    <stop offset="100%" stop-color="#f7cf92"/>
  </linearGradient>
  <radialGradient id="sunglow" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#ffd9a0" stop-opacity="0.95"/>
    <stop offset="100%" stop-color="#ff9f4a" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="water" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#e8a463"/>
    <stop offset="100%" stop-color="#3b2350"/>
  </linearGradient>`;
  void defs;
  const horizon = 640;
  let b = `<rect width="${W}" height="${H}" fill="url(#sky)"/>`;
  b += stars({ seed: 11, count: 90, w: W, h: 360 });
  // sun
  b += `<circle cx="430" cy="${horizon - 60}" r="230" fill="url(#sunglow)"/>`;
  b += `<rect x="366" y="${horizon - 124}" width="128" height="128" fill="#ffd9a2"/>`;
  b += `<rect x="366" y="${horizon - 124}" width="128" height="16" fill="#fff3d6"/>`;
  // cloud bands (blocky)
  const cr = rng(7);
  for (let i = 0; i < 7; i++) {
    const cy = 180 + cr() * 320;
    const cx = cr() * W;
    const cw = 90 + cr() * 200;
    const ch = 14 + cr() * 16;
    const o = 0.14 + cr() * 0.24;
    b += `<rect x="${f(cx)}" y="${f(cy)}" width="${f(cw)}" height="${f(ch)}" fill="#ffd7ae" opacity="${f(o)}"/>`;
    b += `<rect x="${f(cx + cw * 0.2)}" y="${f(cy - ch)}" width="${f(cw * 0.55)}" height="${f(ch)}" fill="#ffd7ae" opacity="${f(o * 0.7)}"/>`;
  }
  // distant ridges
  b += blockRidge({ x0: -20, x1: W + 20, baseY: horizon - 40, amp: 26, step: 26, seed: 3, fill: "#5b2f5e", floorY: H, opacity: 0.85 });
  b += blockRidge({ x0: -20, x1: W + 20, baseY: horizon + 6, amp: 20, step: 22, seed: 9, fill: "#3a1e46", floorY: H });
  // water strip
  b += `<rect x="0" y="${horizon + 46}" width="${W}" height="70" fill="url(#water)" opacity="0.55"/>`;
  for (let i = 0; i < 16; i++) {
    const wy = horizon + 52 + i * 4;
    b += `<rect x="${f(340 + Math.sin(i) * 30)}" y="${wy}" width="${f(120 - i * 5)}" height="2" fill="#ffcf9a" opacity="${f(0.35 - i * 0.02)}"/>`;
  }
  // foreground land
  b += blockRidge({ x0: -20, x1: W + 20, baseY: horizon + 118, amp: 16, step: 20, seed: 21, fill: "#1c1030", floorY: H });
  // house + tree silhouettes on the ridge
  b += voxelHouse({ x: 292, y: horizon + 124, w: 118, h: 92, wall: "#150c26", roof: "#0e0819", window: "#ffc46b" });
  b += voxelTree({ x: 470, y: horizon + 126, u: 15, trunk: "#150c26", leaf: "#150c26", leafDark: "#0e0819" });
  b += voxelTree({ x: 560, y: horizon + 130, u: 10, trunk: "#150c26", leaf: "#150c26", leafDark: "#0e0819" });
  b += voxelTree({ x: 176, y: horizon + 132, u: 11, trunk: "#150c26", leaf: "#150c26", leafDark: "#0e0819" });
  // fence posts
  for (let i = 0; i < 9; i++) b += `<rect x="${f(90 + i * 26)}" y="${f(horizon + 96)}" width="6" height="28" fill="#150c26"/>`;
  b += `<rect x="90" y="${horizon + 100}" width="${8 * 26}" height="5" fill="#150c26"/>`;
  b += pixelDust({ seed: 5, count: 90, w: W, h: H, y0: 120, y1: horizon, color: "#ffd7ae", opacity: 0.35 });
  b += vignette(W, H, 0.5);
  return svg(W, H, skyDef, b);
}

/** SkyBlock — floating island with a tree, violet/cyan sky. */
function sceneSkyblock() {
  const defs = `
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#0a0e1a"/>
    <stop offset="28%" stop-color="#2a1a5c"/>
    <stop offset="58%" stop-color="#4a2a8f"/>
    <stop offset="82%" stop-color="#2f5fa8"/>
    <stop offset="100%" stop-color="#1a3f78"/>
  </linearGradient>
  <radialGradient id="halo" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#8b5cf6" stop-opacity="0.55"/>
    <stop offset="100%" stop-color="#8b5cf6" stop-opacity="0"/>
  </radialGradient>`;
  let b = `<rect width="${W}" height="${H}" fill="url(#sky)"/>`;
  b += stars({ seed: 31, count: 150, w: W, h: 620 });
  b += `<circle cx="400" cy="430" r="300" fill="url(#halo)"/>`;
  // cloud bands
  const cr = rng(17);
  for (let i = 0; i < 9; i++) {
    const cy = 150 + cr() * 620;
    const cx = cr() * W - 60;
    const cw = 120 + cr() * 260;
    b += `<rect x="${f(cx)}" y="${f(cy)}" width="${f(cw)}" height="${f(10 + cr() * 14)}" fill="#a5b4fc" opacity="${f(0.06 + cr() * 0.12)}"/>`;
  }
  // far islands
