  // dangling vine blocks
  for (let i = 0; i < 5; i++)
    b += `<rect x="${f(300 + i * 46)}" y="${f(504 + (i % 3) * 26)}" width="10" height="${f(30 + (i % 2) * 24)}" fill="#1c9d7c" opacity="0.7"/>`;
