/** Prison — dim corridor, cell bars, cold blue glow. */
function scenePrison() {
  const defs = `
  <linearGradient id="wall" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#0b1120"/>
    <stop offset="100%" stop-color="#131c30"/>
  </linearGradient>
  <radialGradient id="lamp" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#7dd3fc" stop-opacity="0.85"/>
    <stop offset="100%" stop-color="#3b82f6" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="floorg" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#1b2740"/>
    <stop offset="100%" stop-color="#070b14"/>
  </linearGradient>`;
  const vpX = 400;
  const vpY = 500;
  let b = `<rect width="${W}" height="${H}" fill="url(#wall)"/>`;
  // receding floor + ceiling wedges
  b += `<path d="M 0 ${H} L ${vpX} ${vpY} L ${W} ${H} Z" fill="url(#floorg)"/>`;
  b += `<path d="M 0 0 L ${vpX} ${vpY} L ${W} 0 Z" fill="#080d18"/>`;
  // side walls with stone block courses receding
  for (let i = 1; i <= 9; i++) {
    const t = i / 10;
    const x = vpX * t;
    const yTop = vpY * t;
    const yBot = H - (H - vpY) * t;
    b += `<path d="M ${f(x)} ${f(yTop)} L ${f(x)} ${f(yBot)}" stroke="#1e2b45" stroke-width="${f(4 - t * 3)}" opacity="0.7"/>`;
    b += `<path d="M ${f(W - x)} ${f(yTop)} L ${f(W - x)} ${f(yBot)}" stroke="#1e2b45" stroke-width="${f(4 - t * 3)}" opacity="0.7"/>`;
  }
  // horizontal stone courses on the floor
  for (let i = 1; i <= 12; i++) {
    const t = Math.pow(i / 12, 1.8);
    const y = vpY + (H - vpY) * t;
    const inset = (1 - t) * vpX;
    b += `<path d="M ${f(inset)} ${f(y)} L ${f(W - inset)} ${f(y)}" stroke="#25344f" stroke-width="2" opacity="${f(0.25 + t * 0.4)}"/>`;
  }
  // ceiling caged lamps + light pools
  const lamps = [
    [vpY + 30, 1.0],
    [vpY - 120, 0.62],
    [vpY - 210, 0.38],
  ];
  for (const [ly, sc] of lamps) {
    b += `<circle cx="${vpX}" cy="${f(ly)}" r="${f(190 * sc)}" fill="url(#lamp)" opacity="${f(0.5 * sc + 0.2)}"/>`;
    b += `<rect x="${f(vpX - 34 * sc)}" y="${f(ly - 14 * sc)}" width="${f(68 * sc)}" height="${f(16 * sc)}" fill="#cbe8ff" opacity="0.9"/>`;
    b += `<rect x="${f(vpX - 40 * sc)}" y="${f(ly - 20 * sc)}" width="${f(80 * sc)}" height="${f(6 * sc)}" fill="#1e2b45"/>`;
    // light pool on floor
    b += `<ellipse cx="${vpX}" cy="${f(ly + 300 * sc)}" rx="${f(200 * sc)}" ry="${f(40 * sc)}" fill="#3b82f6" opacity="${f(0.18 * sc)}" filter="url(#softglow)"/>`;
  }
  // cell bars — foreground left and right, receding
  function bars(side) {
    let s = "";
    const dir = side === "l" ? 1 : -1;
    const baseX = side === "l" ? 0 : W;
    for (let i = 0; i < 7; i++) {
      const t = i / 9;
      const x = baseX + dir * (60 + i * 34) * (1 - t * 0.35);
      const yTop = vpY * (Math.abs(x - vpX) < 1 ? 1 : 1 - Math.abs(x - baseX) / vpX) ;
      void yTop;
      const tt = Math.abs(x - baseX) / vpX;
      const ty = vpY * tt;
      const by = H - (H - vpY) * tt;
      const wdt = Math.max(4, 16 * (1 - tt));
      s += `<rect x="${f(x - wdt / 2)}" y="${f(ty)}" width="${f(wdt)}" height="${f(by - ty)}" fill="#0d1524"/>`;
      s += `<rect x="${f(x - wdt / 2)}" y="${f(ty)}" width="${f(wdt * 0.3)}" height="${f(by - ty)}" fill="#38507a" opacity="0.55"/>`;
    }
    return s;
  }
  b += bars("l");
  b += bars("r");
  // horizontal bar rails
  b += `<rect x="0" y="560" width="250" height="12" fill="#0d1524"/><rect x="${W - 250}" y="560" width="250" height="12" fill="#0d1524"/>`;
  b += `<rect x="0" y="760" width="250" height="14" fill="#0d1524"/><rect x="${W - 250}" y="760" width="250" height="14" fill="#0d1524"/>`;
  // dust motes in the beam
  b += pixelDust({ seed: 61, count: 90, w: W, h: H, y0: 380, y1: 900, color: "#93c5fd", opacity: 0.4 });
  b += vignette(W, H, 0.75);
  return svg(W, H, defs, b);
}

