/** Lifesteal — glowing pixel heart on near-black. */
function sceneLifesteal() {
  const defs = `
  <radialGradient id="bg" cx="50%" cy="45%" r="62%">
    <stop offset="0%" stop-color="#2a0a16"/>
    <stop offset="60%" stop-color="#120610"/>
    <stop offset="100%" stop-color="#07030a"/>
  </radialGradient>
  <radialGradient id="hglow" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#ff2d55" stop-opacity="0.7"/>
    <stop offset="100%" stop-color="#ff2d55" stop-opacity="0"/>
  </radialGradient>`;
  let b = `<rect width="${W}" height="${H}" fill="url(#bg)"/>`;
  b += pixelDust({ seed: 101, count: 200, w: W, h: H, color: "#ff4d6d", opacity: 0.28 });
  b += `<circle cx="400" cy="450" r="330" fill="url(#hglow)"/>`;

  // classic 8-bit heart, drawn on a grid of cubes
  const grid = [
    "..XXX..XXX..",
    ".XXXXXXXXXX.",
    "XXXXXXXXXXXX",
    "XXXXXXXXXXXX",
    "XXXXXXXXXXXX",
    ".XXXXXXXXXX.",
    "..XXXXXXXX..",
    "...XXXXXX...",
    "....XXXX....",
    ".....XX.....",
  ];
  const u = 44;
  const gx = 400 - (12 * u) / 2;
  const gy = 450 - (10 * u) / 2;
  let cells = "";
  const r = rng(5);
  for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < grid[row].length; col++) {
      if (grid[row][col] !== "X") continue;
      const shade = row < 2 || (row < 4 && col < 4) ? "#ff5d78" : row > 6 ? "#a80f30" : "#e01840";
      cells += `<rect x="${f(gx + col * u)}" y="${f(gy + row * u)}" width="${u}" height="${u}" fill="${shade}"/>`;
      if (r() > 0.82)
        cells += `<rect x="${f(gx + col * u)}" y="${f(gy + row * u)}" width="${u}" height="${u}" fill="#ffffff" opacity="0.12"/>`;
    }
  }
  // specular pixels (top-left highlight, the 8-bit convention)
  cells += `<rect x="${f(gx + 2 * u)}" y="${f(gy + 1 * u)}" width="${u}" height="${u}" fill="#ffe0e6"/>`;
  cells += `<rect x="${f(gx + 3 * u)}" y="${f(gy + 1 * u)}" width="${u}" height="${u}" fill="#ffb3c0"/>`;
  cells += `<rect x="${f(gx + 2 * u)}" y="${f(gy + 2 * u)}" width="${u}" height="${u}" fill="#ffb3c0"/>`;

  b += `<g filter="url(#bigglow)" opacity="0.55">${cells}</g>`;
  b += cells;

  // a cracked seam through the lower half
  b += `<path d="M ${f(gx + 6 * u)} ${f(gy + 4 * u)} l -22 46 l 30 26 l -26 52 l 24 40" stroke="#2a0410" stroke-width="9" fill="none" stroke-linejoin="miter"/>`;
  // detached shard cubes drifting off
  const shards = [
    [180, 300, 30],
    [640, 360, 24],
    [700, 620, 34],
    [140, 660, 22],
    [560, 220, 18],
    [250, 210, 16],
  ];
  for (const [sx, sy, ss] of shards) {
    b += `<rect x="${sx}" y="${sy}" width="${ss}" height="${ss}" fill="#e01840" opacity="0.85"/>`;
    b += `<rect x="${sx}" y="${sy}" width="${ss}" height="${f(ss * 0.3)}" fill="#ff7d94" opacity="0.9"/>`;
  }
  b += vignette(W, H, 0.7);
  return svg(W, H, defs, b);
}

/** Anarchy — explosive red crate, fire/danger energy. */
function sceneAnarchy() {
  const defs = `
  <radialGradient id="bg" cx="50%" cy="52%" r="70%">
    <stop offset="0%" stop-color="#4a1206"/>
    <stop offset="46%" stop-color="#1c0810"/>
    <stop offset="100%" stop-color="#0a0410"/>
  </radialGradient>
  <radialGradient id="blast" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#ffd166" stop-opacity="0.95"/>
    <stop offset="38%" stop-color="#ff7a1a" stop-opacity="0.6"/>
    <stop offset="100%" stop-color="#ff3b1a" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="crate" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#e03a2a"/>
    <stop offset="100%" stop-color="#8f1c12"/>
  </linearGradient>`;
  let b = `<rect width="${W}" height="${H}" fill="url(#bg)"/>`;
  b += `<circle cx="400" cy="470" r="380" fill="url(#blast)"/>`;
  // radial shockwave spokes (blocky)
  const r = rng(13);
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * Math.PI * 2 + r() * 0.2;
    const d0 = 250 + r() * 60;
    const d1 = d0 + 60 + r() * 190;
    const x0 = 400 + Math.cos(a) * d0;
    const y0 = 470 + Math.sin(a) * d0;
    const x1 = 400 + Math.cos(a) * d1;
    const y1 = 470 + Math.sin(a) * d1;
    b += `<path d="M ${f(x0)} ${f(y0)} L ${f(x1)} ${f(y1)}" stroke="#ff8a3d" stroke-width="${f(4 + r() * 10)}" opacity="${f(0.15 + r() * 0.4)}"/>`;
  }
  // ember cubes
  for (let i = 0; i < 60; i++) {
    const a = r() * Math.PI * 2;
    const d = 220 + r() * 320;
    const s = 6 + r() * 20;
    b += `<rect x="${f(400 + Math.cos(a) * d)}" y="${f(470 + Math.sin(a) * d)}" width="${f(s)}" height="${f(s)}" fill="${r() > 0.5 ? "#ffb347" : "#ff5a2a"}" opacity="${f(0.35 + r() * 0.6)}"/>`;
  }
  // the crate — original design: red block, pale hazard band, corner rivets, lit fuse
  const cx = 400;
  const cy = 500;
  const s = 300;
  b += `<rect x="${f(cx - s / 2 - 22)}" y="${f(cy - s / 2 - 22)}" width="${f(s + 44)}" height="${f(s + 44)}" fill="#ff6a2a" opacity="0.4" filter="url(#softglow)"/>`;
  b += `<rect x="${f(cx - s / 2)}" y="${f(cy - s / 2)}" width="${s}" height="${s}" fill="url(#crate)"/>`;
  b += `<rect x="${f(cx - s / 2)}" y="${f(cy - s / 2)}" width="${s}" height="18" fill="#ff8a6a" opacity="0.75"/>`;
  b += `<rect x="${f(cx - s / 2)}" y="${f(cy - 34)}" width="${s}" height="68" fill="#f6e6c8"/>`;
  b += `<rect x="${f(cx - s / 2)}" y="${f(cy - 34)}" width="${s}" height="10" fill="#ffffff" opacity="0.55"/>`;
  // hazard chevrons on the band
  for (let i = 0; i < 9; i++) {
    b += `<path d="M ${f(cx - s / 2 + i * 34)} ${f(cy + 34)} l 20 -68 l 14 0 l -20 68 Z" fill="#1a0b06" opacity="0.8"/>`;
  }
  // rivets
  for (const [rx, ry] of [
    [cx - s / 2 + 16, cy - s / 2 + 16],
    [cx + s / 2 - 30, cy - s / 2 + 16],
    [cx - s / 2 + 16, cy + s / 2 - 30],
    [cx + s / 2 - 30, cy + s / 2 - 30],
  ])
    b += `<rect x="${f(rx)}" y="${f(ry)}" width="14" height="14" fill="#5c1108"/>`;
  // fuse + spark
  b += `<path d="M ${cx} ${f(cy - s / 2)} q 10 -54 56 -76" stroke="#c9a06a" stroke-width="10" fill="none"/>`;
  b += `<rect x="${f(cx + 44)}" y="${f(cy - s / 2 - 92)}" width="26" height="26" fill="#fff3c4"/>`;
  b += `<rect x="${f(cx + 22)}" y="${f(cy - s / 2 - 114)}" width="70" height="70" fill="#ffd166" opacity="0.55" filter="url(#softglow)"/>`;
  b += vignette(W, H, 0.6);
  return svg(W, H, defs, b);
}

