  const cr = rng(29);
  for (let i = 0; i < 10; i++)
    b += `<rect x="${f(cr() * W - 80)}" y="${f(120 + cr() * 560)}" width="${f(140 + cr() * 260)}" height="${f(14 + cr() * 22)}" fill="#2a0f1c" opacity="${f(0.12 + cr() * 0.2)}"/>`;
  // distant bursts
  b += `<circle cx="180" cy="300" r="120" fill="url(#burst)" opacity="0.8"/>`;
  b += `<circle cx="660" cy="200" r="90" fill="url(#burst)" opacity="0.7"/>`;

  /** One rising missile: blocky fuselage, nose cone, fins, exhaust trail. */
  function missile({ x, y, len, wdt, angle, glow = "#ffb347" }) {
    let m = "";
    m += `<rect x="${f(-wdt * 1.5)}" y="${f(0)}" width="${f(wdt * 3)}" height="${f(len * 3.4)}" fill="url(#trail)" opacity="0.85"/>`;
    m += `<rect x="${f(-wdt / 2)}" y="${f(-len)}" width="${f(wdt)}" height="${f(len)}" fill="#cbd5e1"/>`;
    m += `<rect x="${f(-wdt / 2)}" y="${f(-len)}" width="${f(wdt * 0.3)}" height="${f(len)}" fill="#ffffff" opacity="0.5"/>`;
    m += `<rect x="${f(-wdt / 2)}" y="${f(-len * 0.62)}" width="${f(wdt)}" height="${f(len * 0.16)}" fill="#e0342a"/>`;
    m += `<rect x="${f(-wdt / 2)}" y="${f(-len * 0.34)}" width="${f(wdt)}" height="${f(len * 0.1)}" fill="#e0342a"/>`;
    m += `<path d="M ${f(-wdt / 2)} ${f(-len)} L 0 ${f(-len - wdt * 1.1)} L ${f(wdt / 2)} ${f(-len)} Z" fill="#e0342a"/>`;
    m += `<rect x="${f(-wdt * 1.05)}" y="${f(-len * 0.16)}" width="${f(wdt * 0.55)}" height="${f(len * 0.22)}" fill="#94a3b8"/>`;
    m += `<rect x="${f(wdt * 0.5)}" y="${f(-len * 0.16)}" width="${f(wdt * 0.55)}" height="${f(len * 0.22)}" fill="#94a3b8"/>`;
    m += `<rect x="${f(-wdt * 0.9)}" y="${f(-6)}" width="${f(wdt * 1.8)}" height="${f(wdt * 1.6)}" fill="${glow}" filter="url(#softglow)" opacity="0.9"/>`;
    return `<g transform="translate(${f(x)},${f(y)}) rotate(${angle})">${m}</g>`;
  }
  b += missile({ x: 250, y: 520, len: 120, wdt: 34, angle: -14 });
  b += missile({ x: 560, y: 600, len: 96, wdt: 27, angle: 12 });
  b += missile({ x: 402, y: 380, len: 150, wdt: 42, angle: -3, glow: "#ffd166" });
  // arena walls / launch pads at the bottom
  b += `<rect x="0" y="880" width="${W}" height="${H - 880}" fill="#170a1e"/>`;
  for (let i = 0; i < 16; i++) {
    const bx = i * 52;
    const bh = 24 + ((i * 37) % 5) * 12;
    b += `<rect x="${bx}" y="${f(880 - bh)}" width="48" height="${f(bh)}" fill="#1f0d28"/>`;
    b += `<rect x="${bx}" y="${f(880 - bh)}" width="48" height="5" fill="#4a1f3a"/>`;
  }
  b += pixelDust({ seed: 131, count: 90, w: W, h: H, y0: 150, y1: 880, color: "#ffcf9a", opacity: 0.45 });
  b += vignette(W, H, 0.55);
  return svg(W, H, defs, b);
}

/** Survival Games — two silhouettes squaring off in a forest clearing. */
function sceneSurvivalGames() {
  const defs = `
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#0a0e1a"/>
    <stop offset="34%" stop-color="#152b3a"/>
    <stop offset="66%" stop-color="#2f5a52"/>
    <stop offset="88%" stop-color="#8a7a3c"/>
    <stop offset="100%" stop-color="#c9a martin"/>
  </linearGradient>`;
  const skyDef = `
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#080c18"/>
    <stop offset="32%" stop-color="#142735"/>
    <stop offset="62%" stop-color="#2c5a4e"/>
    <stop offset="86%" stop-color="#9a8340"/>
    <stop offset="100%" stop-color="#d8b467"/>
  </linearGradient>
  <radialGradient id="clearing" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#ffe6a8" stop-opacity="0.55"/>
    <stop offset="100%" stop-color="#ffe6a8" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="shaft" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#ffeec2" stop-opacity="0.34"/>
    <stop offset="100%" stop-color="#ffeec2" stop-opacity="0"/>
  </linearGradient>`;
  void defs;
  let b = `<rect width="${W}" height="${H}" fill="url(#sky)"/>`;
  b += `<circle cx="400" cy="700" r="330" fill="url(#clearing)"/>`;
  // light shafts through the canopy
  for (const [sx, sw, rot] of [
    [230, 90, -7],
    [400, 130, 2],
    [575, 76, 8],
  ]) {
    b += `<g transform="rotate(${rot} ${sx} 200)"><path d="M ${f(sx - sw / 4)} 120 L ${f(sx + sw / 4)} 120 L ${f(sx + sw)} 860 L ${f(sx - sw)} 860 Z" fill="url(#shaft)"/></g>`;
  }
  // background canopy silhouette
  b += blockRidge({ x0: -20, x1: W + 20, baseY: 470, amp: 70, step: 34, seed: 4, fill: "#0d1d26", floorY: -40 });
  // mid-ground trees framing the clearing
  const trees = [
    [58, 780, 26],
    [130, 800, 20],
    [700, 790, 25],
    [760, 810, 18],
    [196, 760, 15],
    [612, 764, 16],
  ];
  for (const [tx, ty, tu] of trees) b += voxelTree({ x: tx, y: ty, u: tu, trunk: "#0a151c", leaf: "#0c1f24", leafDark: "#071216" });
  // far tree trunks in the haze
  const r = rng(37);
  for (let i = 0; i < 12; i++) {
    const tx = r() * W;
    const tw = 12 + r() * 22;
    b += `<rect x="${f(tx)}" y="${f(400 + r() * 60)}" width="${f(tw)}" height="380" fill="#0e2029" opacity="${f(0.35 + r() * 0.3)}"/>`;
  }
  b += `<rect x="0" y="420" width="${W}" height="300" fill="#1d3a3a" opacity="0.28" filter="url(#mist)"/>`;
  // clearing floor
  b += blockRidge({ x0: -20, x1: W + 20, baseY: 800, amp: 12, step: 24, seed: 8, fill: "#0a141a", floorY: H });
  // the two figures, squaring off
  b += voxelFigure({
    x: 236,
    y: 596,
    u: 12,
    body: "#050b10",
    shade: "#02060a",
    accent: "#06b6d4",
    pose: "ready",
    sword: { blade: "#9fe8ff", guard: "#3b82f6", angle: -30, gx: -3.4, gy: 3.6, glow: "#06b6d4" },
  });
  b += voxelFigure({
    x: 566,
    y: 604,
    u: 12,
    body: "#050b10",
    shade: "#02060a",
    accent: "#a855f7",
    pose: "ready",
    flip: true,
    sword: { blade: "#e6c9ff", guard: "#8b5cf6", angle: -30, gx: -3.4, gy: 3.6, glow: "#8b5cf6" },
  });
  // supply crates scattered in the clearing
  for (const [bx, by, bs] of [
    [400, 806, 44],
    [456, 812, 30],
    [340, 816, 26],
  ]) {
    b += `<rect x="${f(bx - bs / 2)}" y="${f(by - bs)}" width="${bs}" height="${bs}" fill="#1a2a1e"/>`;
    b += `<rect x="${f(bx - bs / 2)}" y="${f(by - bs)}" width="${bs}" height="5" fill="#3d5a3a"/>`;
  }
  b += pixelDust({ seed: 151, count: 110, w: W, h: H, y0: 300, y1: 880, color: "#ffeec2", opacity: 0.4 });
  b += vignette(W, H, 0.66);
  return svg(W, H, skyDef, b);
}

