/**
 * Dashboard top-card hero: dramatic floating islands at sunset with a blocky
 * hooded adventurer holding a glowing sword. Composed for the RIGHT side of a
 * wide card — the left third is kept deliberately empty/dark so the card's
 * text can sit over it behind a fade mask.
 */
function sceneTopHero() {
  const w = 1400;
  const h = 760;
  const defs = `
  <linearGradient id="sky" x1="0.15" y1="0" x2="0.85" y2="1">
    <stop offset="0%" stop-color="#0a0e1a"/>
    <stop offset="26%" stop-color="#2b1553"/>
    <stop offset="52%" stop-color="#5c2a6e"/>
    <stop offset="74%" stop-color="#c05a45"/>
    <stop offset="90%" stop-color="#ef9a4e"/>
    <stop offset="100%" stop-color="#f8c477"/>
  </linearGradient>
  <radialGradient id="sunh" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#ffe0ab" stop-opacity="0.95"/>
    <stop offset="45%" stop-color="#ff9f4a" stop-opacity="0.42"/>
    <stop offset="100%" stop-color="#ff7a3d" stop-opacity="0"/>
  </radialGradient>
  <radialGradient id="vhalo" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="#8b5cf6" stop-opacity="0.5"/>
    <stop offset="100%" stop-color="#8b5cf6" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="leftfade" x1="0" y1="0" x2="1" y2="0">
    <stop offset="0%" stop-color="#0a0e1a" stop-opacity="1"/>
    <stop offset="34%" stop-color="#0a0e1a" stop-opacity="0.55"/>
    <stop offset="62%" stop-color="#0a0e1a" stop-opacity="0"/>
  </linearGradient>
  <linearGradient id="botfade" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#0a0e1a" stop-opacity="0"/>
    <stop offset="100%" stop-color="#0a0e1a" stop-opacity="0.75"/>
  </linearGradient>`;
  let b = `<rect width="${w}" height="${h}" fill="url(#sky)"/>`;
  b += stars({ seed: 201, count: 200, w, h: 420 });
  // sun low behind the islands
  b += `<circle cx="900" cy="470" r="380" fill="url(#sunh)"/>`;
  b += `<rect x="838" y="404" width="128" height="128" fill="#ffe3b4" opacity="0.92"/>`;
  b += `<rect x="838" y="404" width="128" height="16" fill="#fff6e0" opacity="0.9"/>`;
  // violet counter-glow upper right (brand tie-in)
  b += `<circle cx="1180" cy="180" r="300" fill="url(#vhalo)"/>`;
  // horizontal cloud strata
  const cr = rng(41);
  for (let i = 0; i < 16; i++) {
    const cy = 120 + cr() * 480;
    const cx = cr() * w - 120;
    const cw = 160 + cr() * 360;
    const ch = 10 + cr() * 20;
    const o = 0.08 + cr() * 0.24;
    b += `<rect x="${f(cx)}" y="${f(cy)}" width="${f(cw)}" height="${f(ch)}" fill="#ffd0a4" opacity="${f(o)}"/>`;
    b += `<rect x="${f(cx + cw * 0.25)}" y="${f(cy - ch)}" width="${f(cw * 0.5)}" height="${f(ch)}" fill="#ffd0a4" opacity="${f(o * 0.6)}"/>`;
  }
  // distant island cluster
  b += floatingIsland({ cx: 1180, cy: 300, w: 150, topH: 16, depth: 90, top: "#6b3f7a", side: "#432756", under: "#2a1740" });
  b += floatingIsland({ cx: 1310, cy: 470, w: 110, topH: 12, depth: 62, top: "#5c3568", side: "#3a2149", under: "#241436" });
  b += floatingIsland({ cx: 640, cy: 250, w: 118, topH: 14, depth: 66, top: "#6b3f7a", side: "#432756", under: "#2a1740" });
  b += floatingIsland({ cx: 1050, cy: 560, w: 190, topH: 20, depth: 120, top: "#7a4a6a", side: "#4a2b4d", under: "#2c1838" });
  // mid island with trees
  b += floatingIsland({ cx: 1128, cy: 392, w: 250, topH: 26, depth: 160, top: "#3d7f6a", side: "#5c3f28", under: "#2a1b3a" });
  b += voxelTree({ x: 1090, cy: 0, y: 392, u: 14, trunk: "#3a2618", leaf: "#2f6f5c", leafDark: "#1c4a3c" });
  b += voxelTree({ x: 1180, y: 396, u: 10, trunk: "#3a2618", leaf: "#2f6f5c", leafDark: "#1c4a3c" });
  // hero island, right-of-centre
  b += `<ellipse cx="880" cy="620" rx="360" ry="150" fill="url(#vhalo)" opacity="0.7"/>`;
  b += floatingIsland({ cx: 880, cy: 560, w: 430, topH: 36, depth: 250, top: "#46a37f", side: "#6b4a2e", under: "#33214a", edge: "#8affd0" });
  b += voxelTree({ x: 1010, y: 560, u: 17, trunk: "#4a3220", leaf: "#2fa07c", leafDark: "#14705a" });
  b += voxelTree({ x: 726, y: 566, u: 12, trunk: "#4a3220", leaf: "#2fa07c", leafDark: "#14705a" });
  // falling debris cubes under the island
  const dr = rng(67);
  for (let i = 0; i < 22; i++) {
    const dx = 720 + dr() * 340;
    const dy = 700 + dr() * 60;
    const ds = 6 + dr() * 18;
    b += `<rect x="${f(dx)}" y="${f(dy)}" width="${f(ds)}" height="${f(ds)}" fill="#4a3055" opacity="${f(0.3 + dr() * 0.5)}"/>`;
  }
  // the adventurer, standing at the island's edge, backlit
  b += `<ellipse cx="860" cy="556" rx="150" ry="46" fill="#ffb066" opacity="0.28" filter="url(#softglow)"/>`;
  b += voxelFigure({
    x: 838,
    y: 356,
    u: 12.5,
    body: "#2a1a52",
    shade: "#1a0f38",
    accent: "#06b6d4",
    pose: "ready",
    sword: { blade: "#a5f3ff", guard: "#8b5cf6", grip: "#2a1c46", angle: -28, gx: -3.6, gy: 3.6, glow: "#22d3ee" },
  });
  // sparks off the blade
  const sr = rng(83);
  for (let i = 0; i < 20; i++) {
    const sx = 700 + sr() * 130;
    const sy = 220 + sr() * 200;
    const ss = 4 + sr() * 10;
    b += `<rect x="${f(sx)}" y="${f(sy)}" width="${f(ss)}" height="${f(ss)}" fill="#a5f3ff" opacity="${f(0.25 + sr() * 0.6)}"/>`;
  }
  b += pixelDust({ seed: 97, count: 140, w, h, y0: 80, y1: 700, color: "#ffd7ae", opacity: 0.35 });
  // masks so the card's text side stays readable
  b += `<rect width="${w}" height="${h}" fill="url(#leftfade)"/>`;
  b += `<rect width="${w}" height="${h}" fill="url(#botfade)"/>`;
  return svg(w, h, defs, b);
}

