"use server";

/**
 * ============================================================================
 * PLACEHOLDER — DELETE THIS FILE WHEN THE freemc-worlds BRANCH LANDS
 * ============================================================================
 * The real implementation of this module is being written in parallel on
 * `feature/freemc-worlds` (worktree /opt/nxeon-wt-worlds). This file exists on
 * `feature/freemc-redesign` for one reason only: the redesigned Overview UI
 * (components/customer/freemc/{GameModeSelector,GameTypeGrid,SavedWorldsPanel,
 * OverviewRedesigned}.tsx) imports these exact names, and `tsc --noEmit` /
 * `next build` cannot pass on this branch against a module that does not exist
 * yet.
 *
 * It is committed as its OWN commit ("Add placeholder…") specifically so the
 * integrator can drop that single commit — or just `git rm` this file — before
 * merging the real one, instead of resolving an add/add conflict by hand.
 *
 * Every function here is inert: it performs no SSH, no Docker, and no DB
 * writes, and returns an explicit "not wired up yet" error. That is deliberate.
 * A half-implemented world switcher that recreates containers would be far
 * worse than one that plainly refuses — see the comment on
 * applyFreeMinecraftPreset in lib/actions-free-minecraft.ts for how much
 * subtlety the real container-recreate path carries.
 *
 * THE CONTRACT (mirrors the conventions in lib/actions-freemc-roles.ts):
 *   - reads  -> `{ ok: true; ... } | { ok: false; error: string }`
 *   - writes -> `(_prev: unknown, formData: FormData) => Promise<{ error?: string }>`
 *     so they drop straight into useActionState *or* a direct
 *     `await action({}, formData)` call from a useTransition handler.
 *
 * If the real module's shapes differ from these, `tsc` will fail loudly at the
 * wiring step, which is the intended safety net — not a surprise.
 */

type Result = { error?: string };

/** One saved world on the free-tier container's data volume. */
export type FreeMcWorld = {
  /** Stable identifier — whatever the real implementation keys worlds by. */
  id: string;
  /** FREEMC_GAME_TYPES key this world was created for (e.g. "skyblock"). */
  gameType: string;
  /** User-supplied name, or null to fall back to the game type's label. */
  label: string | null;
  /** True for the world the container is currently running. */
  active: boolean;
  /** Last time anyone connected to this world. */
  lastPlayedAt: Date | string | null;
};

const NOT_WIRED =
  "Saved worlds aren't available yet — the world-management backend hasn't been deployed.";

export async function listFreeMinecraftWorlds(): Promise<
  { ok: true; worlds: FreeMcWorld[] } | { ok: false; error: string }
> {
  return { ok: false, error: NOT_WIRED };
}

/** Switch the container onto a different game type (and optionally a specific
 *  existing world). Heavy: recreates the container and restarts the server. */
export async function switchFreeMinecraftGameType(
  _prev: unknown,
  _formData: FormData,
): Promise<Result> {
  return { error: NOT_WIRED };
}

/** Apply a game mode (survival/hardcore/creative/peaceful) to the current
 *  world. Does not swap worlds. */
export async function applyFreeMinecraftGameMode(
  _prev: unknown,
  _formData: FormData,
): Promise<Result> {
  return { error: NOT_WIRED };
}

export async function renameFreeMinecraftWorld(
  _prev: unknown,
  _formData: FormData,
): Promise<Result> {
  return { error: NOT_WIRED };
}

/** Destructive. The real implementation must refuse to delete the world the
 *  container is currently running — the UI disables it, but the server action
 *  is the actual enforcement point. */
export async function deleteFreeMinecraftWorld(
  _prev: unknown,
  _formData: FormData,
): Promise<Result> {
  return { error: NOT_WIRED };
}

"use client";

/**
 * "GAME MODE — How you play": the compact 4-up row at the top of the
 * redesigned free-Minecraft Overview tab.
 *
 * Deliberately the *lighter* of the two selectors on the page. Game TYPE (the
 * cinematic grid below it) is the page's visual centre of gravity; mode is a
 * small utility switch, so it gets small square cards, a thin violet ring when
 * selected, and no imagery at all. Keeping the two treatments this far apart is
 * the whole point — they're different weights of decision.
 *
 * Applying a mode does NOT swap worlds, so there's no "this recreates your
 * server" warning here (that copy lives in GameTypeGrid). The live-vs-restart
 * wording follows the convention already used by the Settings tab's field
 * pills in FreeMcDashboard.tsx: "applies instantly" / "restarts to apply".
 */

import { useState, useTransition } from "react";
import { applyFreeMinecraftGameMode } from "@/lib/actions-freemc-worlds";

export type FreeMcGameMode = {
  label: string;
  description: string;
  /** "live" if it takes effect without a restart. Anything else (including
   *  undefined) is treated as restart-to-apply, which is the honest default:
   *  `gamemode` has no live equivalent that survives a reconnect. See
   *  liveRconCommandFor() in lib/free-minecraft-control.ts. */
  phase?: "live" | "restart";
};

/* Flat, single-colour icons — small enough that anything more detailed would
   turn to mush at 28px. One per known mode key, plus a neutral fallback so an
   unrecognised key still renders a card instead of a hole. */
function ModeIcon({ modeKey, className }: { modeKey: string; className?: string }) {
  const common = { className, viewBox: "0 0 24 24", "aria-hidden": true } as const;
  switch (modeKey) {
    case "survival": // grass block
      return (
        <svg {...common} fill="none">
          <path d="M3 8.2 12 4l9 4.2v7.6L12 20l-9-4.2V8.2Z" fill="#6b4a2e" />
          <path d="M3 8.2 12 4l9 4.2-9 3.4-9-3.4Z" fill="#3fbf7f" />
          <path d="M3 8.2 12 11.6v8.4l-9-4.2V8.2Z" fill="#000" fillOpacity="0.22" />
        </svg>
      );
    case "hardcore": // heart
      return (
        <svg {...common} fill="none">
          <path
            d="M12 20.5 4.2 13a4.7 4.7 0 0 1 6.6-6.6l1.2 1.1 1.2-1.1A4.7 4.7 0 1 1 19.8 13L12 20.5Z"
            fill="#f43f5e"
          />
          <path d="M8.4 8.1h2v2h-2v-2Z" fill="#fff" fillOpacity="0.65" />
        </svg>
      );
    case "creative": // paint palette
      return (
        <svg {...common} fill="none">
          <path
            d="M12 3.2c-5 0-8.8 3.6-8.8 8.2 0 4.6 3.4 8.4 8 8.4 1.6 0 2.4-.9 2.4-1.9 0-.9-.7-1.4-.7-2.2 0-.8.6-1.4 1.5-1.4h1.8c3 0 4.6-2 4.6-4.6 0-3.8-3.6-6.5-8.8-6.5Z"
            fill="#a78bfa"
          />
          <circle cx="7.7" cy="11" r="1.5" fill="#22d3ee" />
          <circle cx="11" cy="7.6" r="1.5" fill="#f59e0b" />
          <circle cx="15.4" cy="8.6" r="1.5" fill="#f43f5e" />
        </svg>
      );
    case "peaceful": // dove
      return (
        <svg {...common} fill="none">
          <path
            d="M20.4 6.1c-1.1.5-2 .6-3.1.4-1-1.6-2.7-2.2-4.3-1.6-1.7.7-2.6 2.4-2.3 4.2C7.4 8.7 5 7 3.3 4.4c-1.2 3 .1 6.2 2.6 7.9-.8.1-1.6-.1-2.3-.5.2 2.3 1.9 4.1 4.1 4.5-.8.5-1.8.7-2.8.6 1.3 1.8 3.6 2.6 5.8 2.1 4.4-1 7.2-4.9 7-9.3.8-.5 1.4-1.2 1.9-2Z"
            fill="#7dd3fc"
          />
          <circle cx="14.6" cy="8.1" r="0.9" fill="#0a101f" />
        </svg>
      );
    default:
      return (
        <svg {...common} fill="none">
          <rect x="4" y="4" width="16" height="16" rx="3" fill="#8a70fb" />
        </svg>
      );
  }
}

function CheckBadge({ small = false }: { small?: boolean }) {
  return (
    <span
      className={`absolute grid place-items-center rounded-full bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow-lg ${
        small ? "right-2 top-2 h-5 w-5" : "right-3 top-3 h-7 w-7"
      }`}
    >
      <svg viewBox="0 0 24 24" className={small ? "h-3 w-3" : "h-4 w-4"} fill="none" aria-hidden>
        <path d="m5 12.5 4.5 4.5L19 7.5" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </span>
  );
}

export function GameModeSelector({
  modes,
  activeMode,
}: {
  modes: Record<string, FreeMcGameMode>;
  activeMode: string | null;
}) {
  // Optimistic highlight: the server's own value is the source of truth, but a
  // click has to move the ring immediately or it reads as "nothing happened"
  // during the round-trip. Same reasoning as the old preset grid.
  const [chosen, setChosen] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  const selected = chosen ?? activeMode;
  const entries = Object.entries(modes);

  function apply(key: string) {
    if (pending) return;
    setChosen(key);
    setError(null);
    setBusyKey(key);
    startTransition(async () => {
      const fd = new FormData();
      fd.set("gameMode", key);
      const res = await applyFreeMinecraftGameMode({}, fd);
      setBusyKey(null);
      if (res?.error) {
        setError(res.error);
        setChosen(null);
      }
    });
  }

  return (
    <section>
      <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
        <h3 className="section-label">
          Game mode <span className="text-slate-600">— how you play</span>
        </h3>
        <p className="text-xs text-slate-500">Keeps your world. Only the rules change.</p>
      </div>

      {error && (
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="mt-3 grid grid-cols-2 gap-3 lg:grid-cols-4">
        {entries.map(([key, mode]) => {
          const isSelected = selected === key;
          const isBusy = busyKey === key;
          return (
            <button
              key={key}
              type="button"
              onClick={() => apply(key)}
              disabled={pending}
              aria-pressed={isSelected}
              className={`relative flex flex-col items-start gap-1.5 rounded-xl border px-3.5 py-3 text-left transition-all duration-150 disabled:cursor-not-allowed ${
                isSelected
                  ? "border-brand-400/50 bg-brand-500/10"
                  : "border-white/[0.08] bg-white/[0.02] hover:border-white/20 hover:bg-white/[0.05]"
              }`}
              style={isSelected ? { boxShadow: "0 0 18px -4px rgb(111 71 245 / 0.45)" } : undefined}
            >
              {isSelected && <CheckBadge small />}
              <ModeIcon modeKey={key} className="h-7 w-7" />
              <span className="text-sm font-semibold text-[var(--fg)]">{mode.label}</span>
              <span className="text-xs leading-snug text-slate-500">{mode.description}</span>
              <span
                className={`mt-0.5 rounded-full px-2 py-0.5 text-[10px] font-semibold ${
                  mode.phase === "live"
                    ? "bg-emerald-500/10 text-emerald-300"
                    : "bg-amber-500/10 text-amber-300"
                }`}
              >
                {isBusy ? "applying…" : mode.phase === "live" ? "applies instantly" : "restarts to apply"}
              </span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

"use client";

/**
 * "GAME TYPE — What you play": the cinematic card grid that is the primary
 * visual selector on the redesigned free-Minecraft Overview tab.
 *
 * Each card is dominated by its type's hero image (public/games/art/
 * freemc-<type>_hero.jpg — original 4:5 voxel illustrations authored by
 * scripts/gen-freemc-art.mjs, composed with their subject in the upper ~60% so
 * the bottom scrim never covers it). A type without a heroImage degrades to a
 * plain brand gradient rather than an empty box, so adding a new game type
 * never ships a broken card while its art is still being drawn.
 *
 * Switching type is the heavy operation on this page — it swaps the world and
 * recreates the container — so selection and application are deliberately two
 * separate steps, with the warning copy sitting on the confirm bar where it
 * cannot be missed.
 */

import { useState, useTransition } from "react";
import { switchFreeMinecraftGameType } from "@/lib/actions-freemc-worlds";

export type FreeMcGameType = {
  label: string;
  description: string;
  /** Public path under /public. Optional — see the gradient fallback below. */
  heroImage?: string;
  /** Honest one-line note about what still needs doing in-game. */
  setupNote?: string;
};

/** Deterministic gradient for types that have no art yet, so the fallback still
 *  looks like a considered card rather than a missing asset. */
function fallbackGradient(key: string): string {
  const palettes = [
    "from-brand-700 via-brand-500 to-accent-blue",
    "from-navy-800 via-brand-600 to-accent-cyan",
    "from-brand-800 via-accent-blue to-brand-400",
  ];
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return palettes[h % palettes.length];
}

export function GameTypeGrid({
  types,
  activeType,
}: {
  types: Record<string, FreeMcGameType>;
  activeType: string | null;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  const entries = Object.entries(types);
  // Only a selection that actually CHANGES something gets a confirm bar —
  // re-clicking the type you're already running shouldn't offer to restart you.
  const pendingChange = selected && selected !== activeType ? selected : null;

  function confirm() {
    if (!pendingChange || pending) return;
    setError(null);
    startTransition(async () => {
      const fd = new FormData();
      fd.set("gameType", pendingChange);
      const res = await switchFreeMinecraftGameType({}, fd);
      if (res?.error) setError(res.error);
      else setSelected(null);
    });
  }

  return (
    <section>
      <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
        <h3 className="section-label">
          Game type <span className="text-slate-600">— what you play</span>
        </h3>
        <p className="text-xs text-slate-500">{entries.length} ways to play, all free.</p>
      </div>

      <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
        {entries.map(([key, type]) => {
          const isActive = activeType === key;
          const isSelected = selected === key;
          const ring = isSelected || (isActive && !selected);
          return (
            <button
              key={key}
              type="button"
              onClick={() => setSelected(key)}
              disabled={pending}
              aria-pressed={isSelected}
              className={`group relative aspect-[4/5] overflow-hidden rounded-2xl border text-left transition-all duration-200 disabled:cursor-not-allowed ${
                ring
                  ? "border-brand-400/70"
                  : "border-white/[0.08] hover:border-brand-400/40"
              }`}
              style={
                ring
                  ? { boxShadow: "0 0 0 1px rgb(138 112 251 / 0.45), 0 0 34px -6px rgb(111 71 245 / 0.75)" }
                  : undefined
              }
            >
              {type.heroImage ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={type.heroImage}
                  alt=""
                  aria-hidden
                  loading="lazy"
                  className="absolute inset-0 h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.06]"
                />
              ) : (
                <span
                  className={`absolute inset-0 bg-gradient-to-br ${fallbackGradient(key)}`}
                  aria-hidden
                />
              )}

              {/* Scrim: transparent over the art, opaque under the text. */}
              <span
                aria-hidden
                className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-navy-950 via-navy-950/85 to-transparent"
              />

              {isSelected && (
                <span className="absolute right-2.5 top-2.5 grid h-8 w-8 place-items-center rounded-full bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow-lg">
                  <svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" aria-hidden>
                    <path
                      d="m5 12.5 4.5 4.5L19 7.5"
                      stroke="currentColor"
                      strokeWidth="3"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </span>
              )}
              {isActive && !isSelected && (
                <span className="absolute left-2.5 top-2.5 rounded-full border border-emerald-400/30 bg-emerald-500/20 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300 backdrop-blur-sm">
                  Active
                </span>
              )}

              <span className="absolute inset-x-0 bottom-0 flex flex-col gap-1 p-3">
                <span className="text-sm font-bold leading-tight text-white drop-shadow">{type.label}</span>
                <span className="line-clamp-2 text-[11px] leading-snug text-slate-300">
                  {type.description}
                </span>
              </span>
            </button>
          );
        })}
      </div>

      {error && (
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}

      {pendingChange && (
        <div className="mt-4 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-amber-400/25 bg-amber-500/[0.07] px-4 py-3.5">
          <div className="min-w-0">
            <p className="text-sm font-semibold text-amber-200">
              Switch to {types[pendingChange]?.label}?
            </p>
            <p className="mt-0.5 text-xs leading-relaxed text-amber-200/70">
              Applying this switches your world and restarts your server. Types that add plugins take a
              little longer the first time while they download.
            </p>
            {types[pendingChange]?.setupNote && (
              <p className="mt-1 text-xs text-amber-300/80">{types[pendingChange]!.setupNote}</p>
            )}
          </div>
          <div className="flex shrink-0 gap-2">
            <button type="button" className="btn-ghost text-sm" onClick={() => setSelected(null)} disabled={pending}>
              Cancel
            </button>
            <button type="button" className="btn-primary text-sm" onClick={confirm} disabled={pending}>
              {pending ? "Switching…" : "Switch & restart"}
            </button>
          </div>
        </div>
      )}
    </section>
  );
}

"use client";

/**
 * "Saved worlds" — a collapsed-by-default panel under the Game Type grid.
 *
 * Collapsed by default on purpose, for two reasons: it keeps the Overview tab's
 * focus on the two selectors above it, and listing worlds costs an SSH
 * round-trip to freemc-host (same reasoning as app/dashboard/games/page.tsx
 * only fetching the free-tier tab's status when that tab is actually open) —
 * so nothing is fetched until someone expands the panel.
 *
 * Delete is two-step and is additionally disabled for the running world. The
 * disabled control is a convenience, NOT the enforcement point: the server
 * action is expected to refuse deleting the active world regardless of what the
 * UI sends.
 */

import { useCallback, useState, useTransition } from "react";
import {
  listFreeMinecraftWorlds,
  switchFreeMinecraftGameType,
  renameFreeMinecraftWorld,
  deleteFreeMinecraftWorld,
  type FreeMcWorld,
} from "@/lib/actions-freemc-worlds";

function formatLastPlayed(value: Date | string | null): string {
  if (!value) return "Never played";
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return "Never played";
  const mins = Math.floor((Date.now() - d.getTime()) / 60_000);
  if (mins < 1) return "Played just now";
  if (mins < 60) return `Played ${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `Played ${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `Played ${days}d ago`;
  return `Played ${d.toLocaleDateString()}`;
}

export function SavedWorldsPanel({ typeLabels }: { typeLabels: Record<string, string> }) {
  const [open, setOpen] = useState(false);
  const [worlds, setWorlds] = useState<FreeMcWorld[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, startLoad] = useTransition();

  // Per-row UI state, keyed by world id so two rows never share a spinner.
  const [renaming, setRenaming] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const [confirmingDelete, setConfirmingDelete] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [acting, startAction] = useTransition();

  const refresh = useCallback(() => {
    startLoad(async () => {
      const res = await listFreeMinecraftWorlds();
      if (res.ok) {
        setWorlds(res.worlds);
        setError(null);
      } else {
        setError(res.error);
        setWorlds(null);
      }
    });
  }, []);

  function toggle() {
    const next = !open;
    setOpen(next);
    if (next && worlds === null && !loading) refresh();
  }

  /** Runs one row action, then re-reads the list so the panel reflects the real
   *  server state rather than an optimistic guess about a container operation. */
  function run(id: string, fn: () => Promise<{ error?: string } | void>) {
    if (acting) return;
    setBusyId(id);
    setError(null);
    startAction(async () => {
      const res = await fn();
      setBusyId(null);
      setConfirmingDelete(null);
      setRenaming(null);
      if (res && "error" in res && res.error) setError(res.error);
      else refresh();
    });
  }

  function switchTo(w: FreeMcWorld) {
    run(w.id, async () => {
      const fd = new FormData();
      fd.set("gameType", w.gameType);
      fd.set("worldId", w.id);
      return switchFreeMinecraftGameType({}, fd);
    });
  }

  function rename(w: FreeMcWorld) {
    const name = renameValue.trim();
    if (!name) return;
    run(w.id, async () => {
      const fd = new FormData();
      fd.set("worldId", w.id);
      fd.set("name", name);
      return renameFreeMinecraftWorld({}, fd);
    });
  }

  function remove(w: FreeMcWorld) {
    run(w.id, async () => {
      const fd = new FormData();
      fd.set("worldId", w.id);
      return deleteFreeMinecraftWorld({}, fd);
    });
  }

  return (
    <section className="rounded-2xl border border-white/[0.06] bg-navy-900/50">
      <button
        type="button"
        onClick={toggle}
        aria-expanded={open}
        className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left"
      >
        <span>
          <span className="text-sm font-semibold text-[var(--fg)]">Saved worlds</span>
          <span className="ml-2 text-xs text-slate-500">
            Every world you&apos;ve played — switch back, rename, or clear one out.
          </span>
        </span>
        <span className="flex shrink-0 items-center gap-2 text-xs text-slate-400">
          {open ? "Hide" : "View saved worlds"}
          <svg
            viewBox="0 0 24 24"
            className={`h-4 w-4 transition-transform duration-200 ${open ? "rotate-180" : ""}`}
            fill="none"
            aria-hidden
          >
            <path d="m6 9 6 6 6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </span>
      </button>

      {open && (
        <div className="border-t border-white/[0.06] px-4 py-4">
          {error && (
            <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
              {error}
            </div>
          )}

          {loading && worlds === null && <p className="text-sm text-slate-500">Loading your worlds…</p>}

          {!loading && worlds !== null && worlds.length === 0 && (
            <p className="text-sm text-slate-500">
              No saved worlds yet — the first time you switch game type, the world you leave behind is kept
              here.
            </p>
          )}

          {worlds !== null && worlds.length > 0 && (
            <ul className="space-y-2">
              {worlds.map((w) => {
                const busy = busyId === w.id && acting;
                const name = w.label || typeLabels[w.gameType] || w.gameType;
                return (
                  <li
                    key={w.id}
                    className={`rounded-xl border px-3.5 py-3 transition-colors ${
                      w.active ? "border-brand-400/40 bg-brand-500/[0.08]" : "border-white/[0.07] bg-white/[0.02]"
                    }`}
                  >
                    <div className="flex flex-wrap items-center justify-between gap-3">
                      <div className="min-w-0">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="truncate text-sm font-medium text-[var(--fg)]">{name}</span>
                          <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-slate-400">
                            {typeLabels[w.gameType] || w.gameType}
                          </span>
                          {w.active && (
                            <span className="rounded-full border border-emerald-400/25 bg-emerald-500/15 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300">
                              Playing now
                            </span>
                          )}
                        </div>
                        <p className="mt-0.5 text-xs text-slate-500">{formatLastPlayed(w.lastPlayedAt)}</p>
                      </div>

                      <div className="flex shrink-0 flex-wrap items-center gap-1.5">
                        {!w.active && (
                          <button
                            type="button"
                            className="btn-secondary px-3 py-1.5 text-xs"
                            onClick={() => switchTo(w)}
                            disabled={acting}
                          >
                            {busy ? "Working…" : "Switch to this world"}
                          </button>
                        )}
                        <button
                          type="button"
                          className="btn-ghost px-3 py-1.5 text-xs"
                          onClick={() => {
                            setRenaming(renaming === w.id ? null : w.id);
                            setRenameValue(w.label ?? "");
                            setConfirmingDelete(null);
                          }}
                          disabled={acting}
                        >
                          Rename
                        </button>
                        <button
                          type="button"
                          className="btn-ghost px-3 py-1.5 text-xs text-red-300 disabled:text-slate-600"
                          onClick={() => {
                            setConfirmingDelete(confirmingDelete === w.id ? null : w.id);
                            setRenaming(null);
                          }}
                          disabled={acting || w.active}
                          title={w.active ? "You can't delete the world you're currently playing." : undefined}
                        >
                          Delete
                        </button>
                      </div>
                    </div>

                    {renaming === w.id && (
                      <div className="mt-3 flex flex-wrap items-center gap-2">
                        <input
                          className="input max-w-xs flex-1"
                          value={renameValue}
                          onChange={(e) => setRenameValue(e.target.value)}
                          maxLength={40}
                          placeholder={typeLabels[w.gameType] || w.gameType}
                          aria-label="World name"
                        />
                        <button
                          type="button"
                          className="btn-secondary px-3 py-1.5 text-xs"
                          onClick={() => rename(w)}
                          disabled={acting || !renameValue.trim()}
                        >
                          {busy ? "Saving…" : "Save name"}
                        </button>
                        <button
                          type="button"
                          className="btn-ghost px-3 py-1.5 text-xs"
                          onClick={() => setRenaming(null)}
                          disabled={acting}
                        >
                          Cancel
                        </button>
                      </div>
                    )}

                    {confirmingDelete === w.id && (
                      <div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-lg border border-red-500/25 bg-red-500/[0.07] px-3 py-2.5">
                        <p className="text-xs text-red-200/85">
                          Delete <span className="font-semibold">{name}</span> for good? Everything built in this
                          world is gone — this can&apos;t be undone.
                        </p>
