              disabled={loading || acting}
            >
              {loading ? "Refreshing…" : "Refresh"}
            </button>
          )}
        </div>
      )}
    </section>
  );
}

"use client";

/**
 * The redesigned contents of the free-Minecraft dashboard's Overview tab —
 * a drop-in replacement for the old `Overview` ("Quick-start presets") in
 * FreeMcDashboard.tsx.
 *
 * It replaces one flat list of 12 presets with the two decisions people
 * actually make, separated and weighted very differently:
 *
 *   1. GAME MODE  — how you play (survival/hardcore/creative/peaceful).
 *      Compact, iconographic, light-touch. Keeps your world.
 *   2. GAME TYPE  — what you play (vanilla/skyblock/prison/…).
 *      Large cinematic art cards. The page's visual centre. Swaps your world
 *      and restarts the server, so it's an explicit two-step confirm.
 *
 * …plus a collapsed "Saved worlds" panel so a world you've switched away from
 * is something you can get back to, rename, or clear out.
 *
 * Deliberately does NOT render a Quick Actions panel, a Server Info panel or a
 * Resource Usage panel: the server card directly above the tab strip already
 * owns name/address/status/power controls, and duplicating them here would
 * give two places to look for the same truth.
 *
 * ---------------------------------------------------------------------------
 * WIRING (done in FreeMcDashboard.tsx once the freemc-worlds backend lands):
 *
 *   {tab === "overview" && (
 *     <OverviewRedesigned
 *       gameTypes={gameTypes}       // FREEMC_GAME_TYPES, passed from the server
 *       gameModes={gameModes}       // FREEMC_GAME_MODES, ditto
 *       activeType={server.gameType}
 *       activeMode={server.gameMode}
 *     />
 *   )}
 *
 * The two tables arrive as PROPS rather than being imported here, because
 * lib/free-minecraft-control.ts pulls in ssh2/node:crypto and can never be
 * imported from a client component — the same reason the old Overview took
 * `presets` as a prop.
 * ---------------------------------------------------------------------------
 */

import { GameModeSelector, type FreeMcGameMode } from "./GameModeSelector";
import { GameTypeGrid, type FreeMcGameType } from "./GameTypeGrid";
import { SavedWorldsPanel } from "./SavedWorldsPanel";

/**
 * Hero art for the server card at the top of the dashboard. Original voxel
 * illustration (floating islands at sunset, hooded adventurer, glowing blade)
 * authored as SVG by scripts/gen-freemc-art.mjs — not a Minecraft asset.
 *
 * The image is baked with its own left-to-right and bottom fades so it dissolves
 * into the card instead of ending on a hard edge; `FreeMcTopCardHero` adds one
 * more scrim on top so the card's text stays legible at any card width.
 */
export const FREEMC_TOP_CARD_HERO = "/games/art/freemc-dashboard_hero.jpg";

/**
 * Drop this inside the top server card (which needs `relative overflow-hidden`)
 * as its FIRST child, so the existing card content paints over it:
 *
 *   <div className="card relative overflow-hidden flex flex-wrap ...">
 *     <FreeMcTopCardHero />
 *     …existing name / address / stats / power buttons…
 *   </div>
 */
export function FreeMcTopCardHero() {
  return (
    <span aria-hidden className="pointer-events-none absolute inset-y-0 right-0 w-full select-none sm:w-[68%]">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={FREEMC_TOP_CARD_HERO}
        alt=""
        className="h-full w-full object-cover object-right"
        loading="lazy"
      />
      <span className="absolute inset-0 bg-gradient-to-r from-navy-900 via-navy-900/70 to-transparent" />
      <span className="absolute inset-0 bg-gradient-to-t from-navy-900/60 to-transparent" />
    </span>
  );
}

export function OverviewRedesigned({
  gameTypes,
  gameModes,
  activeType,
  activeMode,
}: {
  gameTypes: Record<string, FreeMcGameType>;
  gameModes: Record<string, FreeMcGameMode>;
  activeType: string | null;
  activeMode: string | null;
}) {
  const typeLabels = Object.fromEntries(
    Object.entries(gameTypes).map(([key, t]) => [key, t.label]),
  );

  return (
    <div className="space-y-6">
      <div className="card space-y-7">
        <GameModeSelector modes={gameModes} activeMode={activeMode} />
        <div className="h-px bg-white/[0.06]" />
        <GameTypeGrid types={gameTypes} activeType={activeType} />
      </div>

      <SavedWorldsPanel typeLabels={typeLabels} />
    </div>
  );
}

